class Solution {
    static const long long MOD=1000000007LL;
    long long power(long long a,long long b){long long v=1;
        while(b){if(b&1)v=v*a%MOD;a=a*a%MOD;b>>=1;}return v;}
public:
    int minNonZeroProduct(int p){long long mx=(1LL<<p)-1;
        return (int)((mx%MOD)*power((mx-1)%MOD,(mx-1)/2)%MOD);
    }
};
